import{_ as a,o as t,c as n,a2 as d}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Módulo: Bandeja de Entrada","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/bandeja-entrada.md","filePath":"modulos/bandeja-entrada.md"}'),o={name:"modulos/bandeja-entrada.md"};function s(i,e,r,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[d(`<h1 id="modulo-bandeja-de-entrada" tabindex="-1">Módulo: Bandeja de Entrada <a class="header-anchor" href="#modulo-bandeja-de-entrada" aria-label="Permalink to &quot;Módulo: Bandeja de Entrada&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/Inbox.tsx</code> · <code>Backend/handlers/inbox-module/</code></p><p>Sistema de mensajería interna y notificaciones. Centraliza las comunicaciones entre personas y las alertas automáticas que generan otros módulos.</p><h2 id="gestion-de-mensajes" tabindex="-1">Gestión de mensajes <a class="header-anchor" href="#gestion-de-mensajes" aria-label="Permalink to &quot;Gestión de mensajes&quot;">​</a></h2><ul><li>Envío de mensajes individuales o grupales.</li><li>Tipos de mensaje: <strong>Normal</strong>, <strong>Alerta</strong>, <strong>Urgente</strong>.</li><li>Adjuntar archivos.</li><li>Marcar como leído / no leído.</li><li>Archivar mensajes.</li></ul><h2 id="notificaciones-automaticas" tabindex="-1">Notificaciones automáticas <a class="header-anchor" href="#notificaciones-automaticas" aria-label="Permalink to &quot;Notificaciones automáticas&quot;">​</a></h2><p>La bandeja es el destino de los eventos que emiten otros módulos a través del <code>EventBus</code>:</p><table tabindex="0"><thead><tr><th>Evento</th><th>Origen</th><th>Resultado</th></tr></thead><tbody><tr><td><code>document.assigned</code></td><td><a href="/manual/modulos/documentos.html">Documentos</a></td><td>Notificación de documento por firmar</td></tr><tr><td><code>incident.created</code></td><td><a href="/manual/modulos/incidentes.html">Incidentes</a></td><td>Alerta al prevencionista</td></tr></tbody></table><p>Además ofrece:</p><ul><li>Notificaciones push en tiempo real.</li><li>Contador de mensajes no leídos.</li><li>Alertas destacadas para mensajes urgentes.</li></ul><h2 id="estructura-inboxtable" tabindex="-1">Estructura (InboxTable) <a class="header-anchor" href="#estructura-inboxtable" aria-label="Permalink to &quot;Estructura (InboxTable)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>recipientId   personaId del destinatario (PK)</span></span>
<span class="line"><span>messageId     ID del mensaje (SK)</span></span>
<span class="line"><span>senderId      personaId del remitente</span></span>
<span class="line"><span>tenantId      FK</span></span>
<span class="line"><span>tipo          normal | alerta | urgente</span></span>
<span class="line"><span>asunto / cuerpo / adjuntos</span></span>
<span class="line"><span>leido         BOOL</span></span>
<span class="line"><span>archivado     BOOL</span></span>
<span class="line"><span>createdAt</span></span></code></pre></div><p>La PK es <code>recipientId</code> (la persona destinataria), lo que permite consultar de forma eficiente la bandeja de cada persona. Un GSI por <code>senderId</code> permite ver lo enviado.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/inbox/send</code></td><td>Enviar mensaje</td></tr><tr><td><code>GET</code></td><td><code>/inbox</code></td><td>Obtener mensajes</td></tr><tr><td><code>PUT</code></td><td><code>/inbox/{id}/read</code></td><td>Marcar como leído</td></tr><tr><td><code>PUT</code></td><td><code>/inbox/{id}/archive</code></td><td>Archivar</td></tr><tr><td><code>DELETE</code></td><td><code>/inbox/{id}</code></td><td>Eliminar</td></tr></tbody></table>`,15)])])}const h=a(o,[["render",s]]);export{m as __pageData,h as default};
